const inputData = $input.first().json.body.args;

// Split comma-separated strings into arrays, trimming whitespace
const requestIds = inputData.request_id.split(',').map(id => id.trim());
const invoiceAmounts = inputData.invoice_amount.split(',').map(amt => amt.trim());

// Safety check: make sure counts match before pairing them up
if (requestIds.length !== invoiceAmounts.length) {
  throw new Error(
    `Mismatch: ${requestIds.length} request IDs but ${invoiceAmounts.length} invoice amounts. ` +
    `request_id="${inputData.request_id}", invoice_amount="${inputData.invoice_amount}"`
  );
}

// Build one output item per request_id/invoice_amount pair
const outputItems = requestIds.map((requestId, index) => {
  return {
    json: {
      request_id: requestId,
      invoice_amount: invoiceAmounts[index],
      email: inputData.email,
      customer_name: inputData.customer_name,
      disposition: inputData.disposition,
      notes: inputData.notes,
      call_timestamp: inputData.call_timestamp,
      promised_date: inputData.promised_date,
      payment_method: inputData.payment_method,
      promised_amount: inputData.promised_amount,
      total_amount_due: inputData.total_amount_due
    }
  };
});

return outputItems;
